import{c as t,Q as a,j as d,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"ClaudeDevs：Fable 5 在 Claude Code 快速入門指南（Thread）","description":"","frontmatter":{"url":"https://x.com/ClaudeDevs/status/2064394919549210774","title":"ClaudeDevs：Fable 5 在 Claude Code 快速入門指南（Thread）","author":"ClaudeDevs","archived":"2026-06-15T00:00:00.000Z","handle":"@ClaudeDevs","published":"2026-06-09T00:00:00.000Z","score":"8.6/10","stats":"12,089 likes · 952 retweets","tags":["fable-5","claude-code","getting-started","how-to","thread"],"type":"tweet-thread"},"headers":[],"relativePath":"research/tweets/2026-06-09-@ClaudeDevs-210774.md","filePath":"research/tweets/2026-06-09-@ClaudeDevs-210774.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-06-09-@ClaudeDevs-210774.md"};function s(l,e,n,u,i,c){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="claudedevs-fable-5-在-claude-code-快速入門指南-thread" tabindex="-1">ClaudeDevs：Fable 5 在 Claude Code 快速入門指南（Thread） <a class="header-anchor" href="#claudedevs-fable-5-在-claude-code-快速入門指南-thread" aria-label="Permalink to &quot;ClaudeDevs：Fable 5 在 Claude Code 快速入門指南（Thread）&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/ClaudeDevs/status/2064394919549210774" target="_blank" rel="noreferrer">https://x.com/ClaudeDevs/status/2064394919549210774</a><strong>作者</strong>：ClaudeDevs（@ClaudeDevs） <strong>發布日期</strong>：2026-06-09 <strong>收錄日期</strong>：2026-06-15 <strong>類型</strong>：tweet-thread <strong>統計</strong>：12,089 likes · 952 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Claude Fable 5 is here. New model generation, new way of working.</p><p>Here&#39;s how to get started in Claude Code and on the Claude Platform: 🧵</p><p>1/ In Claude Code: run <code>claude update</code> to get latest. Type <code>/model fable</code> to switch. Set <code>/effort</code> to <code>high</code> or <code>max</code> for complex tasks.</p><p>2/ Key differences from Opus 4.8:</p><ul><li>Can&#39;t disable thinking (set thinking:disabled → 400 error)</li><li>Temperature parameter removed</li><li>Counts as ~2× Opus toward your usage plan</li></ul><p>3/ Best first prompt: ask Fable to audit your CLAUDE.md and skills files for contradictions, stale rules, and patterns written for weaker models.</p><p>4/ The unit economics: Fable as orchestrator + Opus/Sonnet as workers = best performance-to-cost ratio for most workflows.</p><p>5/ Available in Claude Code, Cowork, and API (after June 22).</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>10/10</td><td><code>claude update</code>、<code>/model fable</code>、audit CLAUDE.md 的完整逐步操作</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>官方操作指南，有新限制資訊但非原創分析</td></tr><tr><td>C. 證據品質 (20%)</td><td>8/10</td><td>具體錯誤碼（400）、計費說明（2× Opus）、最佳實踐模式有根據</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>涵蓋 thinking 不可關閉、temperature 移除等重要技術限制</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>所有 Fable 5 用戶必讀，適用面最廣</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.6/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Fable 5 技術限制（thinking 強制、temperature 移除、2× 計費）應整合進 pilot-shared-preflights 或 Fable 使用規則。</p>',16)])])}const C=t(o,[["render",s]]);export{p as __pageData,C as default};
